def valid(number):
    """Return True if number is a valid Luhn card number.

    The input is a string. Spaces are ignored.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")

    if len(digits) < 2:
        return False

    if any(ch < "0" or ch > "9" for ch in digits):
        return False

    total = 0
    for position, ch in enumerate(reversed(digits)):
        digit = ord(ch) - ord("0")
        if position % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
